"""Report installed versions of given distributions."""
import pkg_resources


def dependency_report(names: list[str]) -> dict[str, str | None]:
    """Return a dict mapping each name to the installed version string or None if not installed."""
    # Build a case-insensitive map of installed distributions: lowercase name -> version
    installed = {dist.project_name.lower(): dist.version for dist in pkg_resources.working_set}
    result = {}
    for name in names:
        version = installed.get(name.lower())
        result[name] = version
    return result

